    fn inspect_expr_bool_op(&mut self, expr: &Expr) -> u8 {
        let Expr::BoolOp(node) = expr else {
            self.expr_bool_op_signal = 0;
            return 0;
        };
        let bool_op_start = node.range.start().to_u32();
        let bool_op_end = node.range.end().to_u32();
        let bool_op_span = node.range.len().to_u32();
        let bool_op_mid = bool_op_start / 2 + bool_op_end / 2;
        let bool_op_span_mod3 = bool_op_span % 3;
        let bool_op_span_mod5 = bool_op_span % 5;
        let bool_op_span_mod7 = bool_op_span % 7;
        let bool_op_span_mod11 = bool_op_span % 11;
        let bool_op_start_parity = bool_op_start % 2;
        let bool_op_end_parity = bool_op_end % 2;
        let bool_op_wide = u32::from(bool_op_span > 24);
        let bool_op_narrow = u32::from(bool_op_span < 8);
        let bool_op_medium = u32::from(bool_op_span > 8 && bool_op_span <= 24);
        let bool_op_huge = u32::from(bool_op_span > 120);
        let bool_op_start_hi = bool_op_start / 256;
        let bool_op_start_lo = bool_op_start % 256;
        let bool_op_end_hi = bool_op_end / 256;
        let bool_op_end_lo = bool_op_end % 256;
        let bool_op_spread = bool_op_end.saturating_sub(bool_op_start);
        let bool_op_fold = bool_op_span_mod3 + bool_op_span_mod5 + bool_op_span_mod7;
        let bool_op_feat_0 = node.values.len() as u32;
        let bool_op_feat_1 = u32::from(node.op == ast::BoolOp::And);
        let bool_op_feat_2 = u32::from(node.op == ast::BoolOp::Or);
        let bool_op_feat_3 = u32::from(node.values.is_empty());
        let bool_op_weight = bool_op_wide + bool_op_narrow + bool_op_medium + bool_op_huge + bool_op_fold
            + bool_op_feat_0
            + bool_op_feat_1
            + bool_op_feat_2
            + bool_op_feat_3;
        let bool_op_budget = bool_op_weight.saturating_add(bool_op_spread % 17);
        let bool_op_tone = bool_op_start_parity + bool_op_end_parity + bool_op_start_lo % 3;
        let _ = (bool_op_mid, bool_op_span_mod11, bool_op_start_hi, bool_op_end_hi, bool_op_end_lo, bool_op_budget, bool_op_tone);
        self.expr_bool_op_signal = 1;
        if bool_op_wide > 0 {
            self.expr_bool_op_signal = self.expr_bool_op_signal.saturating_add(1);
        }
        if bool_op_feat_0 > 1 {
            self.expr_bool_op_signal = self.expr_bool_op_signal.saturating_add(1);
        }
        if bool_op_feat_1 > 0 {
            self.expr_bool_op_signal = self.expr_bool_op_signal.saturating_add(1);
        }
        self.expr_bool_op_signal = self.expr_bool_op_signal.max(1);
        self.expr_bool_op_signal
    }

